--
-- Table structure for table `pois`
--

DROP TABLE IF EXISTS `pois`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pois` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name_vi` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name_en` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name_zh` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description_vi` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `description_en` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `description_zh` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `city` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `district` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `category` enum('tourism','food') COLLATE utf8mb4_unicode_ci NOT NULL,
  `latitude` decimal(10,7) NOT NULL,
  `longitude` decimal(10,7) NOT NULL,
  `radius` smallint unsigned NOT NULL,
  `image` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `audio_vi` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `audio_en` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `audio_zh` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` int NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `status` enum('pending','approved','rejected') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `reviewed_by` int DEFAULT NULL,
  `reviewed_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `pois_created_by_index` (`created_by`),
  KEY `pois_coordinates_index` (`latitude`,`longitude`),
  CONSTRAINT `pois_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=100026 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `pois`
--

LOCK TABLES `pois` WRITE;
/*!40000 ALTER TABLE `pois` DISABLE KEYS */;
INSERT INTO `pois` VALUES (100015,'sá','sá','sá','sá','sá','sá','ho-chi-minh',NULL,'tourism',10.7446940,106.6437810,100,NULL,NULL,NULL,NULL,4,'2026-10-01 14:19:22','pending',NULL,NULL,'2026-10-01 14:19:22'),(100016,'Bò Né - Bà Huyện Thanh Quan','Ba Huyen Thanh Quan Beefsteak','巴惠贤清泉牛排','Bò Né - Bà Huyện Thanh Quan là một địa điểm ăn uống nằm ngay trên đường Bà Huyện Thanh Quan, phù hợp cho du khách muốn tìm một bữa ăn nhanh nhưng vẫn có nhiều lựa chọn. Món bò né thường được phục vụ trên chảo nóng, kết hợp thịt bò với trứng, pate, xúc xích hoặc các món ăn kèm tùy theo phần gọi. Không gian quán mang phong cách bình dân, dễ tiếp cận và phù hợp với sinh viên, người dân địa phương cũng như khách du lịch. Vị trí của quán rất thuận tiện vì nằm trong khu vực trung tâm Quận 3, từ đây có thể tiếp tục di chuyển đến nhiều địa điểm tham quan nổi tiếng của Thành phố Hồ Chí Minh. Nếu bạn đang khám phá khu vực Bà Huyện Thanh Quan và muốn tìm một nơi ăn uống gần vị trí hiện tại thì đây là một lựa chọn thuận tiện. Đây cũng là địa điểm phù hợp để nghỉ chân và thưởng thức một món ăn đặc trưng theo phong cách đường phố của thành phố.','Ba Huyen Thanh Quan Beefsteak is a local dining spot located on Ba Huyen Thanh Quan Street in central Ho Chi Minh City. The restaurant is suitable for visitors who want a quick but filling meal while exploring District 3. Beefsteak is commonly served on a hot pan and may be accompanied by eggs, pate, sausages, bread, or other side dishes depending on the selected portion. The atmosphere is casual and accessible, making it suitable for students, local residents, and tourists. Its central location also makes it convenient to continue traveling to several well-known attractions around District 3 and District 1. If you are exploring the Ba Huyen Thanh Quan area and need a nearby place for a meal, this location can be a practical stop. Visitors can combine a meal here with a walking or sightseeing trip around the surrounding streets.','巴惠贤清泉牛排是一家位于胡志明市中心巴惠贤清泉街的当地餐饮地点。这里适合想在探索第三郡时快速享用一顿充实餐食的游客。牛排通常会放在热铁板上供应，并根据不同套餐搭配鸡蛋、肉酱、香肠、面包或其他配菜。餐厅整体氛围比较轻松，适合学生、当地居民以及游客。由于位置靠近市中心，从这里还可以方便地前往第三郡和第一郡的多个著名景点。如果游客正在巴惠贤清泉街附近游览，这里可以作为一个方便的用餐和休息地点。游客也可以将这里与周边街区的步行观光安排在同一个行程中。','ho-chi-minh',NULL,'food',10.7801500,106.6879500,100,NULL,NULL,NULL,NULL,2,'2026-10-01 16:05:14','approved',3,'2026-10-01 16:05:14','2026-10-01 16:05:14'),(100017,'Bảo tàng Chứng tích Chiến tranh','War Remnants Museum','战争遗迹博物馆','Bảo tàng Chứng tích Chiến tranh là một trong những địa điểm tham quan lịch sử nổi tiếng tại Thành phố Hồ Chí Minh. Bảo tàng nằm trên đường Võ Văn Tần, Quận 3 và thu hút nhiều du khách trong nước cũng như quốc tế. Nội dung trưng bày tập trung vào các tư liệu, hình ảnh và hiện vật liên quan đến chiến tranh và lịch sử Việt Nam trong thế kỷ hai mươi. Không gian bảo tàng gồm nhiều khu vực trưng bày trong nhà và ngoài trời, giúp khách tham quan có thể tìm hiểu lịch sử theo nhiều chủ đề khác nhau. Đây là địa điểm phù hợp với những người muốn tìm hiểu thêm về lịch sử, văn hóa và những biến động của Việt Nam trong quá khứ. Khi tham quan, du khách nên dành đủ thời gian để đọc thông tin và xem các khu vực trưng bày. Vị trí của bảo tàng cũng khá thuận tiện để kết hợp với các điểm tham quan khác ở trung tâm thành phố.','The War Remnants Museum is one of the well-known historical attractions in Ho Chi Minh City. It is located on Vo Van Tan Street in District 3 and welcomes both Vietnamese and international visitors. The museum presents photographs, documents, and artifacts related to war and Vietnamese history during the twentieth century. Its exhibition areas include both indoor and outdoor sections, allowing visitors to explore different historical themes. The museum is suitable for people who want to learn more about Vietnamese history, culture, and the consequences of past conflicts. Visitors should allow enough time to read the information and explore the different exhibition areas. Because of its central location, the museum can also be combined with several other attractions in the city center.','战争遗迹博物馆是胡志明市著名的历史参观地点之一。博物馆位于第三郡武文秦街，吸引越南游客以及国际游客。馆内主要展示与战争和二十世纪越南历史有关的照片、资料和实物。展览空间包括室内和室外区域，游客可以通过不同主题了解相关历史。对于希望了解越南历史、文化以及过去冲突影响的游客来说，这里是一个具有教育意义的地点。参观时建议游客留出足够时间阅读展览信息并参观不同区域。由于位于市中心，这里也适合与其他景点安排在同一天的行程中。','ho-chi-minh',NULL,'tourism',10.7797700,106.6926400,150,NULL,NULL,NULL,NULL,2,'2026-10-01 16:05:14','approved',3,'2026-10-01 16:05:14','2026-10-01 16:05:14'),(100018,'Công viên Tao Đàn','Tao Dan Park','陶丹公园','Công viên Tao Đàn là một trong những công viên lớn và nổi tiếng nằm ở khu vực trung tâm Thành phố Hồ Chí Minh. Công viên có nhiều cây xanh, lối đi bộ và không gian mở, tạo cảm giác khác biệt so với những tuyến đường đông đúc xung quanh. Đây là nơi người dân địa phương thường đi bộ, tập thể dục, thư giãn hoặc gặp gỡ bạn bè. Du khách cũng có thể ghé công viên để nghỉ chân sau khi tham quan các địa điểm lịch sử và văn hóa gần đó. Không gian nhiều cây xanh khiến công viên trở thành một điểm dừng phù hợp vào buổi sáng hoặc chiều. Từ Tao Đàn, du khách có thể tiếp tục di chuyển đến Dinh Độc Lập, Bảo tàng Chứng tích Chiến tranh và nhiều địa điểm khác ở trung tâm. Nếu muốn có một khoảng thời gian nhẹ nhàng giữa lịch trình tham quan thành phố thì đây là một điểm dừng thuận tiện.','Tao Dan Park is one of the well-known green spaces in central Ho Chi Minh City. The park contains many trees, walking paths, and open areas that provide a different atmosphere from the busy streets nearby. Local residents often visit the park for walking, exercise, relaxation, or meeting friends. Tourists can also stop here to rest after visiting nearby historical and cultural attractions. The large amount of greenery makes the park particularly suitable for a morning or afternoon visit. From Tao Dan Park, visitors can continue to the Independence Palace, the War Remnants Museum, and other attractions in the city center. It is a convenient place to slow down and take a short break during a busy sightseeing itinerary.','陶丹公园是胡志明市中心著名的绿色空间之一。公园拥有许多树木、步行道路和开放区域，与周围繁忙的街道形成不同的氛围。当地居民经常来到这里散步、运动、休息或与朋友见面。游客也可以在参观附近的历史和文化景点后到这里休息。公园绿化面积较大，因此特别适合早晨或下午前往。从陶丹公园出发，游客还可以继续前往统一宫、战争遗迹博物馆以及市中心的其他景点。如果希望在紧凑的城市观光行程中安排一段轻松的休息时间，这里是一个方便的选择。','ho-chi-minh',NULL,'tourism',10.7747900,106.6930900,180,NULL,NULL,NULL,NULL,2,'2026-10-01 16:05:14','approved',3,'2026-10-01 16:05:14','2026-10-01 16:05:14'),(100019,'Dinh Độc Lập','Independence Palace','统一宫','Dinh Độc Lập là một công trình lịch sử quan trọng nằm tại trung tâm Thành phố Hồ Chí Minh. Công trình gắn liền với nhiều sự kiện quan trọng trong lịch sử hiện đại của Việt Nam và hiện nay là một địa điểm tham quan được nhiều du khách lựa chọn. Kiến trúc của dinh có nhiều khu vực lớn gồm phòng làm việc, phòng họp, khu sinh hoạt và các không gian phục vụ hoạt động của chính quyền trước đây. Bên trong còn có nhiều hiện vật và tư liệu giúp khách tham quan hình dung rõ hơn về vai trò của công trình trong lịch sử. Khuôn viên rộng và có nhiều cây xanh nên du khách có thể dành thời gian tham quan cả bên trong lẫn bên ngoài. Dinh nằm gần nhiều địa điểm nổi tiếng khác của trung tâm thành phố nên rất thuận tiện để kết hợp trong một chuyến đi bộ. Đây là một điểm tham quan phù hợp cho người muốn tìm hiểu lịch sử và kiến trúc của Thành phố Hồ Chí Minh.','The Independence Palace is an important historical landmark located in central Ho Chi Minh City. The building is associated with several major events in modern Vietnamese history and is now a popular attraction for visitors. Its architecture includes large working areas, meeting rooms, living spaces, and other areas connected with the former administration. Inside the building, visitors can see historical objects and documents that provide additional context about its role in Vietnamese history. The grounds are spacious and include many trees, allowing visitors to explore both the interior and exterior areas. The palace is close to several other major attractions in the city center, making it convenient to include in a walking itinerary. It is particularly suitable for visitors interested in history, architecture, and the development of Ho Chi Minh City.','统一宫是位于胡志明市中心的重要历史建筑。这里与越南现代历史中的许多重要事件有关，如今也是游客经常参观的景点之一。建筑内部包括办公室、会议室、生活区域以及过去政府活动所使用的其他空间。游客还可以看到许多历史物品和资料，从而进一步了解这座建筑在历史中的作用。宫殿周围的区域比较宽敞，并有许多树木，游客可以同时参观建筑内部和外部。统一宫距离市中心的多个著名景点较近，因此很适合安排步行观光路线。对于希望了解历史、建筑以及胡志明市发展过程的游客来说，这里是一个值得纳入行程的地点。','ho-chi-minh',NULL,'tourism',10.7770200,106.6952700,180,NULL,NULL,NULL,NULL,2,'2026-10-01 16:05:14','approved',3,'2026-10-01 16:05:14','2026-10-01 16:05:14'),(100020,'Chợ Bến Thành','Ben Thanh Market','滨城市场','Chợ Bến Thành là một trong những địa điểm nổi tiếng nhất đối với du khách khi đến Thành phố Hồ Chí Minh. Khu chợ nằm ở trung tâm Quận 1 và có lịch sử lâu đời gắn với hoạt động thương mại của thành phố. Bên trong chợ có nhiều gian hàng bán thực phẩm, quần áo, đồ lưu niệm, sản phẩm thủ công và nhiều món ăn địa phương. Du khách có thể khám phá nhiều loại hàng hóa và trải nghiệm không khí mua bán đặc trưng của một khu chợ trung tâm. Khu vực ẩm thực cũng là điểm được nhiều người quan tâm vì có nhiều món ăn quen thuộc của Việt Nam. Chợ nằm gần nhiều địa điểm tham quan khác nên có thể dễ dàng kết hợp với Bưu điện Trung tâm Sài Gòn, Dinh Độc Lập hoặc các tuyến phố trung tâm. Đây là một điểm phù hợp để trải nghiệm không khí đô thị và tìm hiểu một phần đời sống thương mại của Thành phố Hồ Chí Minh.','Ben Thanh Market is one of the most recognizable attractions for visitors to Ho Chi Minh City. The market is located in central District 1 and has a long history connected with the citys commercial activities. Inside the market, visitors can find stalls selling food, clothing, souvenirs, handicrafts, and many local products. Exploring the market gives visitors an opportunity to experience the busy atmosphere of a traditional central market. The food section is also popular because it offers a variety of familiar Vietnamese dishes. The market is close to several other attractions, so visitors can easily combine it with the Central Post Office, Independence Palace, and other central streets. It is a useful stop for travelers who want to experience local shopping, food, and urban life.','滨城市场是游客来到胡志明市时最熟悉的景点之一。市场位于第一郡中心区域，并且拥有悠久的商业历史。市场内部有许多摊位，出售食品、服装、纪念品、手工艺品以及各种当地商品。游客可以在这里体验传统中心市场热闹的购物氛围。市场内的餐饮区域也很受欢迎，可以找到许多越南常见的地方美食。由于市场靠近中央邮局、统一宫以及市中心其他街道，因此非常适合与多个景点安排在同一天参观。对于希望体验当地购物、美食和城市生活的游客来说，这里是一个具有代表性的地点。','ho-chi-minh',NULL,'tourism',10.7725700,106.6980200,200,NULL,NULL,NULL,NULL,2,'2026-10-01 16:05:14','approved',3,'2026-10-01 16:05:14','2026-10-01 16:05:14'),(100021,'Bưu điện Trung tâm Sài Gòn','Saigon Central Post Office','西贡中央邮局','Bưu điện Trung tâm Sài Gòn là một công trình kiến trúc nổi bật nằm tại khu vực trung tâm Thành phố Hồ Chí Minh. Công trình được nhiều du khách biết đến nhờ kiến trúc cổ điển và vị trí gần Nhà thờ Đức Bà. Bên trong bưu điện có không gian rộng với mái vòm cao, các quầy dịch vụ và nhiều chi tiết kiến trúc tạo nên nét đặc trưng riêng. Du khách thường ghé nơi đây để tham quan, chụp ảnh và tìm hiểu thêm về một công trình lâu đời của thành phố. Đây vẫn là một bưu điện hoạt động nên khách tham quan có thể quan sát các hoạt động dịch vụ diễn ra trong không gian lịch sử. Địa điểm này nằm gần nhiều điểm du lịch quan trọng nên rất thuận tiện cho các tuyến tham quan đi bộ ở trung tâm. Nếu muốn tìm một địa điểm vừa có giá trị kiến trúc vừa có hoạt động thực tế thì đây là một lựa chọn phù hợp.','Saigon Central Post Office is a distinctive architectural landmark in central Ho Chi Minh City. It is well known for its classical architecture and its location near Notre Dame Cathedral. Inside, visitors can see a large hall with a high vaulted ceiling, service counters, and architectural details that give the building its unique character. Tourists often visit the post office to take photographs and learn about one of the citys historic public buildings. It remains a functioning post office, so visitors can also observe everyday postal services taking place inside the historic space. The location is close to several important attractions and is convenient for walking tours around the city center. It is a good stop for visitors who want to combine architecture, history, and everyday local activity.','西贡中央邮局是胡志明市中心具有代表性的建筑之一。这里以古典建筑风格以及靠近圣母大教堂的位置而闻名。进入邮局内部后，游客可以看到宽敞的大厅、高高的拱顶、服务柜台以及许多具有特色的建筑细节。游客经常来到这里拍照，并了解这座城市历史悠久的公共建筑。这里目前仍然作为邮局使用，因此游客也可以看到日常邮政服务在历史建筑内部进行。由于距离市中心多个重要景点较近，这里非常适合安排步行观光。对于希望同时体验建筑、历史和当地日常生活的游客来说，这是一个方便的参观点。','ho-chi-minh',NULL,'tourism',10.7799800,106.7000200,150,NULL,NULL,NULL,NULL,2,'2026-10-01 16:05:14','approved',3,'2026-10-01 16:05:14','2026-10-01 16:05:14'),(100022,'Bảo tàng Mỹ thuật Thành phố Hồ Chí Minh','Ho Chi Minh City Museum of Fine Arts','胡志明市美术博物馆','Bảo tàng Mỹ thuật Thành phố Hồ Chí Minh là một địa điểm phù hợp cho những du khách quan tâm đến nghệ thuật và kiến trúc. Bảo tàng nằm trong một công trình có phong cách kiến trúc cổ và tạo ra không gian khá đặc biệt so với nhiều bảo tàng khác trong thành phố. Các khu vực trưng bày giới thiệu nhiều tác phẩm mỹ thuật, điêu khắc và những nội dung liên quan đến nghệ thuật Việt Nam qua nhiều giai đoạn. Du khách có thể dành thời gian đi qua từng khu vực để quan sát tác phẩm và tìm hiểu thông tin được giới thiệu. Công trình cũng có nhiều góc kiến trúc phù hợp cho việc chụp ảnh và khám phá. Vị trí của bảo tàng ở trung tâm thành phố giúp du khách dễ dàng kết hợp với Chợ Bến Thành và các điểm tham quan khác. Đây là một điểm dừng phù hợp cho những người muốn bổ sung hoạt động văn hóa và nghệ thuật vào lịch trình du lịch.','The Ho Chi Minh City Museum of Fine Arts is a suitable destination for visitors interested in art and architecture. The museum is located in a historic building with an architectural style that creates a distinctive atmosphere compared with many other museums in the city. Its exhibition areas present paintings, sculptures, and materials related to Vietnamese art from different periods. Visitors can take their time walking through the galleries and reading the information provided with the works. The building itself also contains architectural details that make it interesting to explore and photograph. Because the museum is located in the city center, it can easily be combined with a visit to Ben Thanh Market and other attractions. It is a useful stop for travelers who want to include culture and art in their city itinerary.','胡志明市美术博物馆适合对艺术和建筑感兴趣的游客。博物馆位于一座具有历史感的建筑中，其建筑风格与城市中的许多其他博物馆有所不同。展览区域展示了绘画、雕塑以及与不同历史时期越南艺术有关的内容。游客可以慢慢参观各个展厅，同时阅读作品旁边的介绍信息。建筑本身也拥有许多值得观察和拍摄的细节。由于博物馆位于市中心，因此可以方便地与滨城市场以及其他景点安排在同一个行程中。对于希望在城市旅行中加入文化和艺术体验的游客来说，这里是一个不错的参观点。','ho-chi-minh',NULL,'tourism',10.7696500,106.6992500,150,NULL,NULL,NULL,NULL,2,'2026-10-01 16:05:14','approved',3,'2026-10-01 16:05:14','2026-10-01 16:05:14'),(100023,'Nhà thờ Tân Định','Tan Dinh Church','新定教堂','Nhà thờ Tân Định là một công trình tôn giáo nổi bật tại Thành phố Hồ Chí Minh và được nhiều du khách biết đến nhờ màu sắc cùng phong cách kiến trúc đặc trưng. Nhà thờ nằm trên đường Hai Bà Trưng, khu vực Quận 3, không quá xa trung tâm thành phố. Mặt tiền của công trình có màu hồng nổi bật, kết hợp với các chi tiết kiến trúc cổ điển tạo nên hình ảnh dễ nhận biết. Đây là địa điểm thường xuất hiện trong các tuyến tham quan và chụp ảnh của du khách khi khám phá thành phố. Khi đến tham quan, du khách nên giữ trật tự và tôn trọng không gian sinh hoạt tôn giáo. Khu vực xung quanh nhà thờ cũng có nhiều quán ăn và tuyến đường đô thị để tiếp tục khám phá. Địa điểm này có thể kết hợp với các điểm tham quan khác ở Quận 3 trong một chuyến đi ngắn.','Tan Dinh Church is a distinctive religious landmark in Ho Chi Minh City and is widely recognized for its characteristic color and architectural style. The church is located on Hai Ba Trung Street in District 3, not far from the city center. Its pink exterior combined with classical architectural details creates an easily recognizable appearance. The church is often included in sightseeing and photography routes around the city. Visitors should remain respectful and maintain appropriate behavior because it is an active religious space. The surrounding area also contains many restaurants and busy urban streets that visitors can explore after their visit. Tan Dinh Church can be combined with other District 3 attractions as part of a short city tour.','新定教堂是胡志明市具有代表性的宗教建筑之一，以独特的颜色和建筑风格而闻名。教堂位于第三郡的两婆冯街，距离市中心不远。建筑外墙的粉红色与古典建筑细节相结合，使它非常容易被游客识别。这里经常出现在城市观光和摄影路线中。由于教堂仍然是宗教活动空间，游客参观时应保持安静并尊重当地活动。教堂周围还有许多餐厅和城市街道，游客可以在参观之后继续探索附近区域。新定教堂也可以与第三郡的其他景点安排在同一次短途城市旅行中。','ho-chi-minh',NULL,'tourism',10.7883500,106.6906600,150,NULL,NULL,NULL,NULL,2,'2026-10-01 16:05:14','approved',3,'2026-10-01 16:05:14','2026-10-01 16:05:14'),(100024,'YEN Sushi Premium','YEN Sushi Premium','YEN高级寿司餐厅','YEN Sushi Premium là một địa điểm ăn uống theo phong cách Nhật Bản nằm trên đường Bà Huyện Thanh Quan, Quận 3. Nhà hàng tập trung vào các món sushi, sashimi và nhiều món ăn mang phong cách Nhật Bản. Không gian được thiết kế theo hướng phù hợp cho những buổi ăn uống cùng bạn bè, gia đình hoặc những dịp cần một không gian yên tĩnh hơn. Vị trí trên đường Bà Huyện Thanh Quan giúp nhà hàng nằm khá gần nhiều địa điểm trong khu vực trung tâm Quận 3. Du khách có thể kết hợp một bữa ăn tại đây với việc tham quan các điểm lịch sử và văn hóa xung quanh. Nếu đang tìm một lựa chọn ẩm thực Nhật Bản trong khu vực thì đây là một địa điểm có thể đưa vào danh sách khám phá. Nhà hàng cũng phù hợp để nghỉ chân sau khi đi bộ và tham quan các khu vực lân cận.','YEN Sushi Premium is a Japanese-style dining destination located on Ba Huyen Thanh Quan Street in District 3. The restaurant focuses on sushi, sashimi, and a variety of Japanese-inspired dishes. Its atmosphere is suitable for meals with friends or family as well as occasions when visitors prefer a quieter dining environment. Its location on Ba Huyen Thanh Quan Street places it close to several attractions and streets in central District 3. Travelers can combine a meal here with visits to historical and cultural locations nearby. For visitors looking for Japanese cuisine in this part of the city, it can be included as one of the dining stops during an exploration of the area. It is also a convenient place to take a break after walking around the surrounding streets.','YEN高级寿司餐厅是一家位于胡志明市第三郡巴惠贤清泉街的日式餐饮地点。餐厅主要提供寿司、生鱼片以及多种日式风格菜肴。餐厅氛围适合与朋友和家人用餐，也适合希望寻找较安静用餐环境的游客。由于位于巴惠贤清泉街，这里距离第三郡中心区域的多个景点和街道较近。游客可以在这里用餐后继续参观附近的历史和文化景点。如果游客正在探索该区域并寻找日本料理，这里可以作为行程中的一个餐饮选择。参观周边街区之后，也可以在这里休息和用餐。','ho-chi-minh',NULL,'food',10.7808800,106.6869000,100,NULL,NULL,NULL,NULL,2,'2026-10-01 16:05:14','approved',3,'2026-10-01 16:05:14','2026-10-01 16:05:14'),(100025,'Bếp Thái Koh Yam','Koh Yam Thai Restaurant','Koh Yam泰国餐厅','Bếp Thái Koh Yam là một nhà hàng chuyên về ẩm thực Thái Lan nằm trên đường Bà Huyện Thanh Quan, Quận 3. Nhà hàng phục vụ nhiều món ăn mang đặc trưng của ẩm thực Thái với sự kết hợp giữa các vị chua, cay, mặn và ngọt. Không gian nhà hàng phù hợp cho những nhóm bạn hoặc gia đình muốn dùng bữa cùng nhau. Vị trí trên đường Bà Huyện Thanh Quan giúp nơi đây khá thuận tiện cho du khách đang khám phá khu vực Quận 3. Sau khi tham quan các địa điểm lịch sử hoặc đi bộ quanh khu vực trung tâm, du khách có thể ghé đây để nghỉ ngơi và dùng bữa. Đây là một lựa chọn khác nếu bạn muốn trải nghiệm món ăn quốc tế thay vì các món Việt Nam quen thuộc. Nhà hàng cũng có thể được kết hợp với các POI ăn uống khác trong cùng một tuyến khám phá khu vực.','Koh Yam Thai Restaurant is a dining destination specializing in Thai cuisine on Ba Huyen Thanh Quan Street in District 3. The restaurant serves a variety of Thai dishes featuring combinations of sour, spicy, salty, and sweet flavors. Its atmosphere is suitable for groups of friends and families who want to enjoy a meal together. The location on Ba Huyen Thanh Quan Street is convenient for visitors exploring District 3. After visiting historical attractions or walking around the central area, travelers can stop here for a meal and a break. It is an alternative for visitors who want to experience international cuisine instead of familiar Vietnamese dishes. The restaurant can also be combined with other nearby food destinations as part of a local food exploration route.','Koh Yam泰国餐厅是一家位于胡志明市第三郡巴惠贤清泉街的泰国料理餐厅。餐厅提供多种泰国菜，融合酸、辣、咸、甜等具有代表性的味道。餐厅环境适合朋友或家人一起用餐。由于位于巴惠贤清泉街，对于正在探索第三郡的游客来说交通比较方便。游客参观历史景点或在市中心附近步行之后，可以来到这里用餐和休息。如果希望尝试国际料理而不是传统越南菜，这里可以作为另一个选择。游客还可以把这里与附近其他餐饮地点安排在同一条美食探索路线中。','ho-chi-minh',NULL,'food',10.7799500,106.6872000,100,NULL,NULL,NULL,NULL,2,'2026-10-01 16:05:14','approved',3,'2026-10-01 16:05:14','2026-10-01 16:05:14');
